-- Danh mục cho website: điểm đến, tour + lịch khởi hành, khách sạn + loại phòng, sân bay + chặng bay phổ biến,
-- đánh giá, và danh sách đăng ký nhận ưu đãi.
--
-- Thiết kế theo nhóm "bảng" của gotrips-web (lib/types.ts) để khi nối trang /tours, /hotels, /flights chỉ cần
-- map thêm cột vào entity, không phải đổi cấu trúc. Chưa tạo các bảng chưa có API nào dùng (ảnh tour, hãng bay,
-- lịch bay, đơn đặt chỗ...).
--
-- Id danh mục là bigint kiểu IDENTITY (GENERATED BY DEFAULT) để dữ liệu mẫu chèn được id cố định: id đang nằm
-- trong cookie đơn đặt chỗ và trong các trang vẫn đọc dữ liệu mock theo id/slug. Chỉ dùng integer/bigint/numeric:
-- Hibernate (ddl-auto: validate) so kiểu cột nghiêm ngặt, smallint không khớp với Integer.

CREATE TABLE destinations (
    id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug      varchar(100) NOT NULL,
    name      varchar(150) NOT NULL,
    region    varchar(100) NOT NULL,
    image_url varchar(500) NOT NULL,
    image_alt varchar(255) NOT NULL,
    CONSTRAINT uq_destinations_slug UNIQUE (slug),
    CONSTRAINT ck_destinations_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);

CREATE TABLE tours (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug              varchar(150) NOT NULL,
    title             varchar(255) NOT NULL,
    destination_id    bigint       NOT NULL,
    duration_days     integer      NOT NULL,
    duration_nights   integer      NOT NULL,
    departure_city    varchar(100) NOT NULL,
    short_description varchar(500) NOT NULL,
    cover_image_url   varchar(500) NOT NULL,
    cover_image_alt   varchar(255) NOT NULL,
    -- Điểm trung bình 0-5 và số đánh giá lưu sẵn (không tính lại từ bảng testimonials).
    rating            numeric(2, 1) NOT NULL DEFAULT 0,
    review_count      integer      NOT NULL DEFAULT 0,
    is_featured       boolean      NOT NULL DEFAULT false,
    -- HIDDEN: tour tạm ẩn, không hiển thị và không được đếm ở bất kỳ API công khai nào.
    status            varchar(10)  NOT NULL DEFAULT 'ACTIVE',
    CONSTRAINT uq_tours_slug UNIQUE (slug),
    CONSTRAINT ck_tours_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT fk_tours_destination FOREIGN KEY (destination_id) REFERENCES destinations (id),
    CONSTRAINT ck_tours_status CHECK (status IN ('ACTIVE', 'HIDDEN')),
    CONSTRAINT ck_tours_duration CHECK (duration_days > 0 AND duration_nights >= 0),
    CONSTRAINT ck_tours_rating CHECK (rating >= 0 AND rating <= 5),
    CONSTRAINT ck_tours_review_count CHECK (review_count >= 0)
);

CREATE INDEX idx_tours_destination_id ON tours (destination_id);

CREATE TABLE tour_departures (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tour_id        bigint  NOT NULL,
    -- Kiểu DATE, không múi giờ: ngày khởi hành là ngày lịch ở Việt Nam.
    departure_date date    NOT NULL,
    -- Giá mỗi khách, VND. original_price là giá gốc trước giảm (null nếu không giảm).
    price          bigint  NOT NULL,
    original_price bigint,
    total_seats    integer NOT NULL,
    booked_seats   integer NOT NULL DEFAULT 0,
    CONSTRAINT fk_tour_departures_tour FOREIGN KEY (tour_id) REFERENCES tours (id) ON DELETE CASCADE,
    CONSTRAINT ck_tour_departures_price CHECK (price > 0),
    CONSTRAINT ck_tour_departures_original_price CHECK (original_price IS NULL OR original_price > 0),
    CONSTRAINT ck_tour_departures_seats CHECK (total_seats > 0 AND booked_seats >= 0 AND booked_seats <= total_seats)
);

CREATE INDEX idx_tour_departures_tour_date ON tour_departures (tour_id, departure_date);

-- Sân bay: khoá chính là mã IATA (web và form tìm vé dùng mã này chứ không dùng id số).
CREATE TABLE airports (
    code       varchar(3)   PRIMARY KEY,
    name       varchar(150) NOT NULL,
    city       varchar(100) NOT NULL,
    -- Thứ tự hiển thị trong danh sách gợi ý: các đầu mối lớn trước.
    sort_order integer      NOT NULL,
    CONSTRAINT ck_airports_code_format CHECK (code ~ '^[A-Z]{3}$')
);

CREATE TABLE flight_routes (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    from_code        varchar(3)   NOT NULL,
    to_code          varchar(3)   NOT NULL,
    duration_minutes integer      NOT NULL,
    -- Giá tham khảo một chiều cho một hành khách, VND: chỉ để gợi ý, không phải giá bán.
    reference_price  bigint       NOT NULL,
    image_url        varchar(500) NOT NULL,
    image_alt        varchar(255) NOT NULL,
    -- "Chặng bay phổ biến" hiện theo sort_order (độ phổ biến), không theo id.
    sort_order       integer      NOT NULL,
    CONSTRAINT fk_flight_routes_from FOREIGN KEY (from_code) REFERENCES airports (code),
    CONSTRAINT fk_flight_routes_to FOREIGN KEY (to_code) REFERENCES airports (code),
    CONSTRAINT uq_flight_routes_from_to UNIQUE (from_code, to_code),
    CONSTRAINT ck_flight_routes_distinct CHECK (from_code <> to_code),
    CONSTRAINT ck_flight_routes_duration CHECK (duration_minutes > 0),
    CONSTRAINT ck_flight_routes_price CHECK (reference_price > 0)
);

CREATE TABLE hotels (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug           varchar(150) NOT NULL,
    name           varchar(200) NOT NULL,
    destination_id bigint       NOT NULL,
    -- Hạng sao của khách sạn (1-5), khác với rating là điểm khách chấm.
    star_rating    integer      NOT NULL,
    area           varchar(150) NOT NULL,
    image_url      varchar(500) NOT NULL,
    image_alt      varchar(255) NOT NULL,
    status         varchar(10)  NOT NULL DEFAULT 'ACTIVE',
    rating         numeric(2, 1) NOT NULL DEFAULT 0,
    review_count   integer      NOT NULL DEFAULT 0,
    description    text         NOT NULL,
    amenities      text[]       NOT NULL DEFAULT '{}',
    check_in_time  time         NOT NULL DEFAULT '14:00',
    check_out_time time         NOT NULL DEFAULT '12:00',
    CONSTRAINT uq_hotels_slug UNIQUE (slug),
    CONSTRAINT ck_hotels_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT fk_hotels_destination FOREIGN KEY (destination_id) REFERENCES destinations (id),
    CONSTRAINT ck_hotels_status CHECK (status IN ('ACTIVE', 'HIDDEN')),
    CONSTRAINT ck_hotels_star_rating CHECK (star_rating BETWEEN 1 AND 5),
    CONSTRAINT ck_hotels_rating CHECK (rating >= 0 AND rating <= 5),
    CONSTRAINT ck_hotels_review_count CHECK (review_count >= 0)
);

CREATE INDEX idx_hotels_destination_id ON hotels (destination_id);

CREATE TABLE hotel_room_types (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    hotel_id        bigint       NOT NULL,
    name            varchar(150) NOT NULL,
    -- Giá MỘT phòng MỘT đêm, VND. "Giá từ" của khách sạn là giá thấp nhất trong các loại phòng của nó.
    price_per_night bigint       NOT NULL,
    -- Số khách tối đa mỗi phòng.
    max_guests      integer      NOT NULL,
    bed_type        varchar(150) NOT NULL,
    area_m2         integer      NOT NULL,
    CONSTRAINT fk_hotel_room_types_hotel FOREIGN KEY (hotel_id) REFERENCES hotels (id) ON DELETE CASCADE,
    CONSTRAINT ck_hotel_room_types_price CHECK (price_per_night > 0),
    CONSTRAINT ck_hotel_room_types_max_guests CHECK (max_guests >= 1),
    CONSTRAINT ck_hotel_room_types_area CHECK (area_m2 > 0)
);

CREATE INDEX idx_hotel_room_types_hotel_id ON hotel_room_types (hotel_id);

CREATE TABLE testimonials (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tour_id       bigint       NOT NULL,
    customer_name varchar(100) NOT NULL,
    customer_city varchar(100) NOT NULL,
    rating        integer      NOT NULL,
    content       text         NOT NULL,
    CONSTRAINT fk_testimonials_tour FOREIGN KEY (tour_id) REFERENCES tours (id) ON DELETE CASCADE,
    CONSTRAINT ck_testimonials_rating CHECK (rating BETWEEN 1 AND 5)
);

CREATE INDEX idx_testimonials_tour_id ON testimonials (tour_id);

-- Đăng ký nhận ưu đãi qua email (form ở Trang chủ). Email luôn chữ thường để UNIQUE bắt được trùng
-- (giống bảng users). Chưa có luồng huỷ đăng ký.
CREATE TABLE newsletter_subscriptions (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email         varchar(254) NOT NULL,
    subscribed_at timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_newsletter_subscriptions_email UNIQUE (email),
    CONSTRAINT ck_newsletter_subscriptions_email_lowercase CHECK (email = lower(email))
);
